# ===================== CONSTANTS & CONFIG =====================
SCREEN_WIDTH, SCREEN_HEIGHT = 1200, 800
FPS = 60
ROBOT_RADIUS = 15
ROBOT_SPEED = 3.5
ROBOT_ACCEL = 0.5
ROBOT_TURN_SPEED = 0.15
