# Weapon definitions
WEAPONS = {
    "blaster": {"damage": 15, "range": 300, "fire_rate": 0.4, "energy_cost": 10, "color": (0, 255, 255), "type": "ranged"},
    "plasma_cannon": {"damage": 35, "range": 400, "fire_rate": 1.2, "energy_cost": 30, "color": (255, 100, 0), "type": "ranged"},
    "melee_knife": {"damage": 25, "range": 40, "fire_rate": 0.3, "energy_cost": 5, "color": (255, 255, 255), "type": "melee"},
