}

# Power-ups
POWERUPS = {
    "health_pack": {"value": 30, "color": (0, 255, 0), "duration": 0},
    "energy_cell": {"value": 40, "color": (0, 100, 255), "duration": 0},
    "speed_boost": {"multiplier": 1.5, "color": (255, 255, 0), "duration": 5.0},
    "damage_boost": {"multiplier": 1.5, "color": (255, 0, 0), "duration": 5.0}
}

# Environmental hazards
HAZARDS = {
    "laser_grid": {"damage_per_sec": 5, "color": (255, 0, 255), "radius": 60},
    "energy_vortex": {"damage_per_sec": 8, "color": (255, 150, 255), "radius": 80}
}

# ===================== UTILITIES =====================
class Vector2:
    def __init__(self, x, y):
        self.x = x
        self.y = y

    def __add__(self, other):
        return Vector2(self.x + other.x, self.y + other.y)

    def __sub__(self, other):
        return Vector2(self.x - other.x, self.y - other.y)

    def __mul__(self, scalar):
        return Vector2(self.x * scalar, self.y * scalar)

    def __truediv__(self, scalar):
        return Vector2(self.x / scalar, self.y / scalar)

    def magnitude(self):
        return math.sqrt(self.x**2 + self.y**2)

    def normalize(self):
        mag = self.magnitude()
        return Vector2(self.x / mag, self.y / mag) if mag > 0 else Vector2(0, 0)

    def distance_to(self, other):
        return math.sqrt((self.x - other.x)**2 + (self.y - other.y)**2)


class Color(Enum):
    RED = (255, 50, 50)
    BLUE = (50, 50, 255)
    GREEN = (50, 255, 50)
    YELLOW = (255, 255, 50)
    PURPLE = (255, 50, 255)
    CYAN = (50, 255, 255)


class Team(Enum):
    RED = "red"
    BLUE = "blue"


class GameState(Enum):
    MENU = auto()
    PLAYING = auto()
    PAUSED = auto()
    GAME_OVER = auto()


# ===================== GAME ENTITIES =====================
class Particle:
    def __init__(self, x, y, color, velocity, life_time):
        self.pos = Vector2(x, y)
        self.velocity = velocity
        self.color = color
        self.life_time = life_time
        self.max_life_time = life_time
        self.size = random.uniform(2, 5)

    def update(self, dt):
        self.pos.x += self.velocity.x * dt
        self.pos.y += self.velocity.y * dt
        self.life_time -= dt
        self.size *= 0.95  # Shrink over time

    def is_alive(self):
        return self.life_time > 0

    def draw(self, screen):
        alpha = self.life_time / self.max_life_time
        pygame.draw.circle(screen, (*self.color, int(255 * alpha)), (int(self.pos.x), int(self.pos.y)), int(self.size))


class Bullet:
    def __init__(self, x, y, direction, weapon_type, owner_team, damage_multiplier=1.0):
        self.pos = Vector2(x, y)
        self.direction = direction.normalize()
        self.weapon = WEAPONS[weapon_type]
        self.speed = 8.0
        self.owner_team = owner_team
        self.damage = self.weapon["damage"] * damage_multiplier
        self.range = self.weapon["range"]
        self.traveled = 0
        self.active = True
        self.color = self.weapon["color"]

    def update(self, dt):
        if not self.active:
            return

        move_vec = self.direction * self.speed * dt
        self.pos.x += move_vec.x
        self.pos.y += move_vec.y
        self.traveled += move_vec.magnitude()

        if self.traveled >= self.range:
            self.active = False

    def draw(self, screen):
        if not self.active:
            return

        # Draw bullet trail
        trail_length = 10
        for i in range(trail_length):
            alpha = (1 - i / trail_length) * 0.5
            trail_pos = Vector2(
                self.pos.x - self.direction.x * i * 3,
                self.pos.y - self.direction.y * i * 3
            )
            pygame.draw.circle(screen, (*self.color, int(255 * alpha)), (int(trail_pos.x), int(trail_pos.y)), 2)

        # Draw bullet core
        pygame.draw.circle(screen, self.color, (int(self.pos.x), int(self.pos.y)), 4)


class PowerUp:
    def __init__(self, x, y, powerup_type):
        self.pos = Vector2(x, y)
        self.type = powerup_type
        self.info = POWERUPS[powerup_type]
        self.radius = 12
        self.active = True
        self.bob_offset = random.uniform(0, math.pi * 2)

    def update(self, dt):
        self.bob_offset += dt * 3

    def draw(self, screen):
        if not self.active:
            return

        # Bobbing effect
        bob_y = math.sin(self.bob_offset) * 3

        # Outer glow
        pygame.draw.circle(screen, (*self.info["color"], 60), (int(self.pos.x), int(self.pos.y + bob_y)), self.radius + 3)
        # Core
        pygame.draw.circle(screen, self.info["color"], (int(self.pos.x), int(self.pos.y + bob_y)), self.radius)

        # Icon
        font = pygame.font.SysFont(None, 16)

