    def update(self, dt: float):
        self.pos += self.velocity * dt * 60
        self.life -= self.decay * dt * 60
        self.size *= 0.98

    def is_dead(self) -> bool:
        return self.life <= 0

    def draw(self, screen):
        alpha = self.life / self.max_life
        color_with_alpha = (*self.color, int(255 * alpha))
        surf = pygame.Surface((self.size * 2, self.size * 2), pygame.SRCALPHA)
        pygame.draw.circle(surf, color_with_alpha, (self.size, self.size), self.size)
        screen.blit(surf, (self.pos.x - self.size, self.pos.y - self.size))


